// NB-09 · spec: .qa/e2e/specs/nearby.md 1.9 · две роли · меняет данные (согласие) → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, reloadLists, GEO } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 180_000 });
  test('приватность — nearby_places отдаёт только свою точку, nearby_recent без координат @iphone @data (#67c751 #ee51bb)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      for (const [me, other] of [[reg1, reg2], [reg2, reg1]] as const) {
        const { recent, places } = await reloadLists(me.page);
        expect(places.length, `nearby_places у ${me.role}`).toBeGreaterThan(0);
        for (const pl of places) {
          expect(Math.abs(Number(pl.lat) - GEO[me.role].latitude), `lat места = своя точка ${me.role}`).toBeLessThanOrEqual(0.0005);
          expect(Math.abs(Number(pl.lng) - GEO[me.role].longitude), `lng места = своя точка ${me.role}`).toBeLessThanOrEqual(0.0005);
          const otherPoint = Math.abs(Number(pl.lat) - GEO[other.role].latitude) < 0.0005 && Math.abs(Number(pl.lng) - GEO[other.role].longitude) < 0.0005;
          expect(otherPoint, 'место не совпадает с точкой другого').toBe(false);
        }
        expect(recent.some((r) => String(r.id) === other.id)).toBe(true);
        for (const r of recent) { expect(r).not.toHaveProperty('lat'); expect(r).not.toHaveProperty('lng'); }
      }
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
